    for (size_t j = 0; j < cols; j += block_size):
      compute: std::size_t i_end = (i + block_size) < rows ? (i + block_size) : rows
      compute: std::size_t j_end = (j + block_size) < cols ? (j + block_size) : cols
      for (size_t ii = i; ii < i_end; ii++):
