bool matrix_blocks_equal_simd(const int* matrix, size_t block_size, size_t rows, size_t cols):
  if matrix == NULL:
    return: false
  if block_size <= 0:
    return: false
  if rows % block_size != 0 || cols % block_size != 0:
    return: false
  compute: std::size_t block_rows = rows / block_size
  compute: std::size_t block_cols = cols / block_size
  for (size_t br = 0; br < block_rows; br++):
    for (size_t bc = 0; bc < block_cols; bc++):
      for (size_t r = 0; r < block_size; r++):
        for vec_base in vector_range(0, block_size):
          lane c = vec_base + lane_id
          where active = c < block_size:
            compute: std::size_t idx1 = r*cols + c
            compute: std::size_t idx2 = (br*block_size + r)*cols + (bc*block_size + c)
            read: matrix[idx1], matrix[idx2]
            if any_lane(matrix[idx1] != matrix[idx2]):
              return: false
  return: true

